#!/usr/bin/env node
/**
 * packages/chat/scripts/generate-db-types.mjs — writes `src/host/db-types.ts`,
 * the package's own `ChatDatabase`: the subset of the platform's generated
 * Supabase types covering exactly the schemas the package reads
 * (PACKAGE-INDEPENDENCE §2.1, slice P6).
 *
 * Source: the full generated file (`supabase gen types` + the platform's
 * patches) — in matrx-frontend, `types/database.types.ts`, which `pnpm db-types`
 * regenerates and then runs this script. Each schema block is copied verbatim,
 * so a query typed against `ChatDatabase` types exactly as it did against the
 * full `Database`.
 *
 * Schemas = `public` + every schema the package source names: `.schema("x")`,
 * `Database["x"]`, `{ schema: "x" }`, `SupabaseClient<Database, "x"`. A schema
 * the code reaches some other way fails type-check (indexing a missing key),
 * which is the signal to name it in EXTRA_SCHEMAS below. Schemas those schemas'
 * own types name (a function returning `Database["canvas"]["Enums"][…]`) are
 * added too, until the set is closed.
 *
 *   node packages/chat/scripts/generate-db-types.mjs [--source <file>] [--check]
 *
 * --check: exit 1 (and say which way) when the committed file differs from what
 * the source would generate now. Never edit the output by hand.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const PKG = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC_DIR = path.join(PKG, "src");
const OUT = path.join(SRC_DIR, "host", "db-types.ts");
const OUT_REL = path.relative(process.cwd(), OUT);

/** Schemas the package reaches without naming them literally. */
const EXTRA_SCHEMAS = [];

const args = process.argv.slice(2);
const at = args.indexOf("--source");
const source = path.resolve(
  at >= 0 ? args[at + 1] : path.join(PKG, "..", "..", "types", "database.types.ts"),
);
const CHECK = args.includes("--check");

function fail(message) {
  console.error(`generate-db-types: ${message}`);
  process.exit(1);
}

if (!fs.existsSync(source)) {
  fail(`no source at ${source}. Pass --source <the full generated database.types.ts>.`);
}

// ── 1. Which schemas the package names ──────────────────────────────────────
const NAME_PATTERNS = [
  /\.schema\(\s*["'`]([a-z_][a-z0-9_]*)["'`]/g,
  /Database\[\s*["']([a-z_][a-z0-9_]*)["']\s*\]/g,
  /\bschema:\s*["']([a-z_][a-z0-9_]*)["']/g,
  /SupabaseClient<\s*(?:Chat)?Database\s*,\s*["']([a-z_][a-z0-9_]*)["']/g,
];
const named = new Set(["public", ...EXTRA_SCHEMAS]);
(function walk(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name !== "node_modules") walk(p);
    } else if (/\.(tsx?|mts|cts)$/.test(entry.name) && p !== OUT) {
      const text = fs.readFileSync(p, "utf8");
      for (const re of NAME_PATTERNS) for (const m of text.matchAll(re)) named.add(m[1]);
    }
  }
})(SRC_DIR);

// ── 2. Split the source into its schema blocks ──────────────────────────────
const lines = fs.readFileSync(source, "utf8").split("\n");
const start = lines.indexOf("export type Database = {");
if (start < 0) fail(`${source} has no "export type Database = {" line.`);
let end = -1;
for (let i = start + 1; i < lines.length; i++) {
  if (lines[i] === "}") {
    end = i;
    break;
  }
}
if (end < 0) fail(`${source}: the Database type never closes.`);

const blocks = new Map(); // name -> lines (including its opening and closing)
let current = null;
for (let i = start + 1; i < end; i++) {
  const open = /^  ([A-Za-z_][A-Za-z0-9_]*): \{$/.exec(lines[i]);
  if (open) {
    current = open[1];
    blocks.set(current, []);
  }
  if (current) blocks.get(current).push(lines[i]);
  if (lines[i] === "  }") current = null;
}
if (!blocks.has("__InternalSupabase")) fail(`${source}: no __InternalSupabase block.`);

// A schema's own types may name another schema (`Database["canvas"]["Enums"]…`
// in a function's args or returns): take the closure, so every reference resolves.
const chosen = new Set([...named].filter((name) => blocks.has(name)));
for (let grew = true; grew; ) {
  grew = false;
  for (const name of [...chosen]) {
    for (const m of blocks.get(name).join("\n").matchAll(/Database\[\s*"([a-z_][a-z0-9_]*)"\s*\]/g)) {
      if (blocks.has(m[1]) && !chosen.has(m[1])) {
        chosen.add(m[1]);
        grew = true;
      }
    }
  }
}
const schemas = [...chosen].sort();
const unknown = [...named].filter((name) => !blocks.has(name)).sort();

// ── 3. Helper types after the Database block (Tables, Enums, …) ─────────────
const helpersEnd = lines.findIndex((line, i) => i > end && line.startsWith("export const Constants"));
const helpers = lines.slice(end + 1, helpersEnd < 0 ? lines.length : helpersEnd).join("\n").trim();
const jsonStart = 0;
const preamble = lines.slice(jsonStart < 0 ? 0 : jsonStart, start).join("\n").trim();

const body = [
  "/**",
  " * GENERATED by packages/chat/scripts/generate-db-types.mjs — never edit by hand.",
  " *",
  " * `ChatDatabase`: the platform's generated Supabase types for exactly the",
  " * schemas this package reads, copied verbatim (PACKAGE-INDEPENDENCE §2.1, P6).",
  " * The host's `db` is a `SupabaseClient<ChatDatabase>`; a host typed with the",
  " * full platform `Database` passes its client unchanged.",
  " *",
  ` * Schemas (${schemas.length}): ${schemas.join(", ")}`,
  " */",
  "",
  "/* eslint-disable */",
  "",
  preamble,
  "",
  "export type ChatDatabase = {",
  ...blocks.get("__InternalSupabase"),
  ...schemas.flatMap((name) => blocks.get(name)),
  "}",
  "",
  "/** The name every call site imports — the same name the full platform file uses. */",
  "export type Database = ChatDatabase",
  "",
  helpers,
  "",
].join("\n");

if (CHECK) {
  const committed = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
  if (committed !== body) {
    fail(
      `${OUT_REL} is out of date with ${path.relative(process.cwd(), source)} ` +
        `(schemas now: ${schemas.join(", ")}). Run: node packages/chat/scripts/generate-db-types.mjs`,
    );
  }
  console.log(`generate-db-types: ${OUT_REL} is current (${schemas.length} schemas).`);
} else {
  fs.writeFileSync(OUT, body);
  console.log(
    `generate-db-types: wrote ${OUT_REL} — ${schemas.length} schemas (${schemas.join(", ")}), ` +
      `${body.split("\n").length} lines.`,
  );
}
if (unknown.length) {
  console.warn(
    `generate-db-types: the package names schema(s) the source does not have: ${unknown.join(", ")}`,
  );
}
